import { getBlogPost, blogPosts } from "@/lib/blog-data"
import { MarkdownRenderer } from "@/components/markdown-renderer"
import { Badge } from "@/components/ui/badge"
import { Calendar, Clock, ArrowLeft } from "lucide-react"
import Link from "next/link"
import { notFound } from "next/navigation"

export async function generateStaticParams() {
  return blogPosts.map((post) => ({
    id: post.id,
  }))
}

export async function generateMetadata({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params
  const post = getBlogPost(id)

  if (!post) {
    return { title: "Post Not Found" }
  }

  return {
    title: `${post.title} | Blog`,
    description: post.excerpt,
  }
}

export default async function BlogPostPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params
  const post = getBlogPost(id)

  if (!post) {
    notFound()
  }

  return (
    <main className="min-h-screen bg-background py-12">
      <article className="container mx-auto max-w-3xl px-4">
        <Link
          href="/#blog"
          className="mb-8 inline-flex items-center gap-2 text-muted-foreground transition-colors hover:text-accent"
        >
          <ArrowLeft className="h-4 w-4" />
          Back to all posts
        </Link>

        <header className="mb-12">
          <Badge variant="secondary" className="mb-4">
            {post.category}
          </Badge>
          <h1 className="mb-6 text-balance text-4xl font-bold tracking-tight md:text-5xl">{post.title}</h1>
          <div className="flex flex-wrap items-center gap-4 text-muted-foreground">
            <div className="flex items-center gap-2">
              <Calendar className="h-4 w-4" />
              <time dateTime={post.date}>
                {new Date(post.date).toLocaleDateString("en-US", {
                  year: "numeric",
                  month: "long",
                  day: "numeric",
                })}
              </time>
            </div>
            <div className="flex items-center gap-2">
              <Clock className="h-4 w-4" />
              <span>{post.readTime}</span>
            </div>
          </div>
        </header>

        <MarkdownRenderer content={post.content} />

        <footer className="mt-16 border-t pt-8">
          <Link
            href="/#blog"
            className="inline-flex items-center gap-2 text-muted-foreground transition-colors hover:text-accent"
          >
            <ArrowLeft className="h-4 w-4" />
            Back to all posts
          </Link>
        </footer>
      </article>
    </main>
  )
}
